Let  $r,k \geq 2$ be integers, and let $b>0$.
Let $(\mathcal{H}_n)_{n \in \mathbb{N}}$ be a sequence of $k$-uniform ordered hypergraphs and set $\hat p_n:=\hat p(\mathcal{H}_n)$ as given by~(17). Let (P1)--(P5) be the following properties. 
\begin{enumerate}
\item[(P1)] Probabilities: $\hat p_n \to 0$ and $\hat p_n v(\mathcal{H}_n) \to \infty$ as $n \to \infty$.
\item[(P2)] Supersaturation: $(\mathcal{H}_n)_{n \in \mathbb{N}}$ is $r$-supersaturated.
\item[(P3)] Bounded degree: 
for any $W \subseteq Y \subseteq [k]$, and any sufficiently large $n \in \mathbb N$  we have
$\Delta_W(\mathcal{H}_{n,Y}) \leq b \frac{e(\mathcal{H}_{n,Y})}{e(\mathcal{H}_{n,W})}$. 

\item[(P4)] Bounded $1$-degree: for any $W \subset Y \subseteq [k]$ with $|W|=1$ and any sufficiently large $n \in \mathbb N$, we have
$\Delta_W(\mathcal{H}_{n,Y}) \leq b \frac{e(\mathcal{H}_{n,Y})}{v(\mathcal{H}_{n})}$.
\item[(P5)] Bounded $2$-degree: there exists a sequence $(X_n)_{n\in\mathbb N}$ of subsets $X_n\subseteq[k]$ with $|X_n|\ge3$ for all $n\in\mathbb N$ such that
\begin{equation}
f_{n,X_n}=\Omega(\hat p_n)
\end{equation}
and 
\begin{equation}
\Delta_{W_n}(\mathcal{H}_{n,X_n}) \cdot \Delta_{W'_n}(\mathcal{H}_{n,X_n})\cdot e(\mathcal{H}_{n,X_n}) \cdot (\hat p_n)^{3|X_n|-2-|W'_n|} = o(1)
\end{equation} 
for any sequences $(W_n)_{n\in\mathbb N}$ and $(W'_n)_{n\in\mathbb N}$ with $W_n,W'_n\subset X_n$, $|W_n|=2$ and $|W'_n|\ge2$.
\end{enumerate}

\medskip

If (P1)--(P4) hold, then there exists a constant $C>0$ such that if $q_n \geq C\hat p_n$ then
\begin{align*}
\lim_{n \rightarrow \infty}  \mathbb{P}[\mathcal{H}^v_{n,q_n} \text{ is $r$-Ramsey}]
= 1.
\end{align*}

If (P1) and (P3)--(P5) hold, then there exists a constant $c>0$ such that if $q_n \leq c\hat p_n$ then
\begin{align*}
\lim_{n \rightarrow \infty}  \mathbb{P}[\mathcal{H}^v_{n,q_n} \text{ is $r$-Ramsey}]
= 0.
\end{align*}

Let $r\geq 2$, $k  \geq 3$ and $\ell\geq 1$ be integers. Let $(S_n)_{n \in \mathbb N}$ be a sequence of finite subsets of abelian groups, $A$ be an $\ell \times k$ integer matrix and set $\hat p_n:=\hat p(A,S_n)$.

Suppose that 
\begin{itemize}
\item[(A1)] $\hat p_n\to 0$ and $|S_n|\hat p_n\to\infty$ as $n\to\infty$;
\item[(A2)] $(S_n)_{n \in \mathbb N}$ is $(A,r)$-supersaturated; 
\item[(A3)] there exists $B\ge1$ such that the pair $(A,S_n)$ is $B$-extendable for all sufficiently large $n\in\mathbb N$;
\item[(A4)] there exists $D>0$ such that for every $W\subset Y\subseteq[k]$ with $|W|=1$ and $w_0\in S_n$, we have $|\mathrm{Sol}_{S_n}^A(w_0,W,Y)|\le D\frac{|\mathrm{Sol}_{S_n}^A(Y)|}{|S_n|}$ for all sufficiently large $n\in\mathbb N$; 
\item[(A5)] $(S_n)_{n \in \mathbb N}$ is compatible with respect to $A$;
\item[(A6)] $(S_n)_{n \in \mathbb N}$ is weakly compatible with respect to $A$.
\end{itemize}
Then there exist constants $c,C>0$ such that
$$\lim _{n \rightarrow \infty} \mathbb P [ S_{n,p} \text{ is } (A,r)\text{-Rado}]=\begin{cases}
0 &\text{ if } p\leq {c}\hat p_n; \\
 1 &\text{ if } p\geq {C}\hat p_n.\end{cases}$$

Let $r\ge2$, $k \ge 3$ and $\ell\geq 1$ be integers. Let $(S_n)_{n\in\mathbb N}$ be a sequence where $S_n$ is either a finite abelian group or $S_n=L^d$ for some finite subset $L$ of a field and $d\in\mathbb N$, for every $n\in\mathbb N$. 
Let $A$ be an $\ell \times k$ integer matrix and set $\hat p_n:=\hat p(A,S_n)$. Suppose that 
\begin{itemize}
\item[(C1)] $\hat p_n \to 0$ and $|S_n|\hat p_n \to \infty$ as $n \to \infty$;
\item[(C2)] $(S_n)_{n \in \mathbb N}$ is $(A,r)$-supersaturated;
\item[(C3)] there exists $0<\varepsilon\leq 1$ such that $(A,S_n)$ is $\varepsilon$-rich for every sufficiently large $n\in\mathbb N$; 
\item[(C4)] $(A,S_n)$ is abundant for every sufficiently large $n\in\mathbb N$;
\item[(C5)] given any  $n\in\mathbb N$ there exists $ X_n\subseteq[k]$ with $|X_n|\ge3$  such that $p_{X_n}(A,S_n)=\Omega(\hat p(A,S_n))$ and for every sequence $(W'_n)_{n\in\mathbb N}$ with $W'_n\subset X_n$ and $|W'_n|\ge2$ we have
$$\frac{p_{W'_n}(A,S_n)}{p_{X_n}(A,S_n)}\to0$$
as $n\to\infty$.
\end{itemize}
Then there exist constants $c,C>0$ such that
$$\lim _{n \rightarrow \infty} \mathbb P [ S_{n,p} \text{ is } (A,r)\text{-Rado}]=\begin{cases}
0 &\text{ if } p\leq {c}|S_n|^{-\frac{1}{m_{S_n}(A)}}; \\
 1 &\text{ if } p\geq {C}|S_n|^{-\frac{1}{m_{S_n}(A)}}.\end{cases}$$
